import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int n = Integer.parseInt(tokens.get(0));
        StringBuilder sb = new StringBuilder(3 * n);
        for (int i = 0; i < n; i++) {
            String next = tokens.get(1 + (i + 1) % n); // the word after the last one wraps around
            sb.append(tokens.get(1 + i).charAt(0)).append(next.charAt(next.length() - 1)).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n int
	fmt.Fscan(in, &n)
	w := make([]string, n)
	for i := range w {
		fmt.Fscan(in, &w[i])
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	for i := 0; i < n; i++ {
		next := w[(i+1)%n] // the word after the last one wraps around
		out.WriteByte(w[i][0])
		out.WriteByte(next[len(next)-1])
		out.WriteByte('\n')
	}
}
